package com.sisge.ms.security;
import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class JwtService { private final String secret; private final long ttl; public JwtService(@Value("${app.jwt.secret}") String s,@Value("${app.jwt.expiration-seconds}") long t){secret=s;ttl=t;if(s==null||s.length()<32)throw new IllegalStateException("JWT_SECRET must have at least 32 characters");} public String create(String email){long exp=Instant.now().plusSeconds(ttl).getEpochSecond();String h=b64("{\"alg\":\"HS256\",\"typ\":\"JWT\"}"),p=b64("{\"sub\":\""+email.replace("\"","")+"\",\"exp\":"+exp+"}");return h+"."+p+"."+sign(h+"."+p);} public String subject(String token){try{String[] a=token.split("\\.");if(a.length!=3||!constant(sign(a[0]+"."+a[1]),a[2]))return null;String json=new String(Base64.getUrlDecoder().decode(a[1]),StandardCharsets.UTF_8);long exp=Long.parseLong(json.replaceAll(".*\"exp\":(\\d+).*","$1"));if(exp<Instant.now().getEpochSecond())return null;return json.replaceAll(".*\"sub\":\"([^\"]+)\".*","$1");}catch(Exception e){return null;}} private String sign(String s){try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return Base64.getUrlEncoder().withoutPadding().encodeToString(mac.doFinal(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} private String b64(String s){return Base64.getUrlEncoder().withoutPadding().encodeToString(s.getBytes(StandardCharsets.UTF_8));}private boolean constant(String a,String b){return java.security.MessageDigest.isEqual(a.getBytes(),b.getBytes());}}
